"""Restrict queries/answers to an allow-list of topics (substring match)."""

from __future__ import annotations

from typing import Any

# Generated by GitHub Copilot - Nov-01-2026
from app.guardrails.models import GuardrailResult


class TopicFilterGuardrail:
    name = "topic_filter"

    async def run(self, text: str, context: dict[str, Any] | None, **params: Any) -> GuardrailResult:
        allowed = params.get("allowed_topics") or []
        action = str(params.get("_action", params.get("action", "warn")))
        if not allowed:
            return GuardrailResult(text=text, blocked=False)

        lower = text.lower()
        ok = any(str(a).lower() in lower for a in allowed)
        if not ok:
            msg = "Content may be outside allowed topics"
            if action == "block":
                return GuardrailResult(text="", blocked=True, warnings=[msg])
            return GuardrailResult(text=text, blocked=False, warnings=[msg])
        return GuardrailResult(text=text, blocked=False)
